using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakA2AllH;
internal sealed class AllEndpointDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Unbounded a2 AllEndpoint", H("Unbounded a2 AllEndpoint"),
        Blocks(Paragraph(Text("For every natural b,c,d with c>=3, c+2<=d and d<b, at k=2+b+c+d and seed 1+2^2+2^(2+b)+2^(2+b+c), construct a permutation sigma of every Fin k label exactly once and j<=k. The literal earWord has complete OriginalOrder at k+1 and doubled seed. Every natural repetition and take, including zero and overlong takes, has its actualSource sum in the old strip [0,modulus(k)/2] or new strip [0,modulus(k)] respectively. Old and new complete repeated totals are separately zero. The exponent transport reuses physical_order and zero_period_transport. This is the full a=2 second-peak unit; the unrestricted Circle problem remains open.")),
            Describe.Lean(DescribeId.Create("a2-all-h-allendpoint-actualsource-second-peak-a2-all-h-joint-lift"), DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FourNegative/SecondPeakA2AllH/AllEndpoint.actualSource_second_peak_a2_all_h_joint_lift"), H("actualSource_second_peak_a2_all_h_joint_lift"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("theorem actualSource_second_peak_a2_all_h_joint_lift (b c d : \u2115)     (hc : 3\u2264c) (hd : c+2\u2264d) (hb : d<b) :     \u2203 sigma : List (Fin (2+b+c+d)), \u2203 j : \u2115, j\u22642+b+c+d \u2227       OriginalOrder (2+b+c+d) (1+2^2+2^(2+b)+2^(2+b+c)) sigma \u2227       OriginalOrder (2+b+c+d+1) (2*(1+2^2+2^(2+b)+2^(2+b+c)))         (earWord (2+b+c+d) sigma j) \u2227       (\u2200 r n : \u2115, ((((List.replicate r sigma).flatten).take n).map         (actualSource (2+b+c+d) (1+2^2+2^(2+b)+2^(2+b+c)))).sum \u2208         Set.Icc (0:\u2124) (modulus (2+b+c+d)/2)) \u2227       (\u2200 r n : \u2115, ((((List.replicate r (earWord (2+b+c+d) sigma j)).flatten).take n).map         (actualSource (2+b+c+d+1) (2*(1+2^2+2^(2+b)+2^(2+b+c))))).sum \u2208         Set.Icc (0:\u2124) (modulus (2+b+c+d))) \u2227       (\u2200 r : \u2115,         (((List.replicate r sigma).flatten).map           (actualSource (2+b+c+d) (1+2^2+2^(2+b)+2^(2+b+c)))).sum=0 \u2227         (((List.replicate r (earWord (2+b+c+d) sigma j)).flatten).map           (actualSource (2+b+c+d+1) (2*(1+2^2+2^(2+b)+2^(2+b+c))))).sum=0)"))), DescribeRole.Theorem)), []));
}
